  1 | import type { Track } from "../types";
  2 | 
  3 | interface PlayerControlsProps {
  4 |   currentTrack: Track | null;
  5 |   currentTrackId: string | null;
  6 |   isPlaying: boolean;
  7 |   isShuffled: boolean;
  8 |   isCompact?: boolean;
  9 |   onPlay: () => void;
 10 |   onPause: () => void;
 11 |   onNext: () => void;
 12 |   onPrev: () => void;
 13 |   onToggleShuffle?: () => void;
 14 |   onToggleFavorite?: (trackId: string) => void;
 15 |   onToggleCompact?: () => void;
 16 | }
 17 | 
 18 | export function PlayerControls({
 19 |   currentTrack,
 20 |   currentTrackId,
 21 |   isPlaying,
 22 |   isShuffled,
 23 |   isCompact = false,
 24 |   onPlay,
 25 |   onPause,
 26 |   onNext,
 27 |   onPrev,
 28 |   onToggleShuffle,
 29 |   onToggleFavorite,
 30 |   onToggleCompact,
 31 | }: PlayerControlsProps) {
 32 |   if (isCompact) {
 33 |     return (
 34 |       <section className="player-controls-compact">
 35 |         <button
 36 |           className="ctrl-btn play-btn"
 37 |           onClick={isPlaying ? onPause : onPlay}
 38 |           title={isPlaying ? "Pausar" : "Tocar"}
 39 |         >
 40 |           {isPlaying ? "⏸" : "▶"}
 41 |         </button>
 42 |         <div className="now-playing-info" key={currentTrack?.id ?? "empty"}>
 43 |           <span className="track-title">
 44 |             {currentTrack ? currentTrack.title : "Nenhuma música tocando"}
 45 |           </span>
 46 |         </div>
 47 |         <button
 48 |           className="compact-toggle-btn"
 49 |           onClick={onToggleCompact}
 50 |           title="Expandir"
 51 |           aria-label="Expandir"
 52 |         >
 53 |           🗖
 54 |         </button>
 55 |       </section>
 56 |     );
 57 |   }
 58 | 
 59 |   return (
 60 |     <section className={`player-controls${isPlaying ? " playing" : ""}`}>
 61 |       <div className="now-playing">
 62 |         {currentTrack?.coverUrl && (
 63 |           <img
 64 |             className="album-art"
 65 |             src={currentTrack.coverUrl}
 66 |             alt={`Capa do álbum${currentTrack.album ? ` — ${currentTrack.album}` : ""}`}
 67 |           />
 68 |         )}
 69 |         <div className="now-playing-info" key={currentTrack?.id ?? "empty"}>
 70 |           <span className="track-title">
 71 |             {currentTrack ? currentTrack.title : "Nenhuma música tocando"}
 72 |           </span>
 73 |           {currentTrack?.artist && (
 74 |             <span className="track-artist">{currentTrack.artist}</span>
 75 |           )}
 76 |           {currentTrack?.album && (
 77 |             <span className="track-album">{currentTrack.album}</span>
 78 |           )}
 79 |         </div>
 80 |         {currentTrackId && onToggleFavorite && (
 81 |           <button
 82 |             className={`favorite-btn ${currentTrack?.isFavorite ? "favorite-active" : ""}`}
 83 |             onClick={() => onToggleFavorite(currentTrackId)}
 84 |             title={currentTrack?.isFavorite ? "Remover dos favoritos" : "Adicionar aos favoritos"}
 85 |             aria-label={currentTrack?.isFavorite ? "Remover dos favoritos" : "Adicionar aos favoritos"}
 86 |           >
 87 |             {currentTrack?.isFavorite ? "♥" : "♡"}
 88 |           </button>
 89 |         )}
 90 |       </div>
 91 | 
 92 |       <div className="controls">
 93 |         <button
 94 |           className={`ctrl-btn shuffle-btn ${isShuffled ? "active" : ""}`}
 95 |           onClick={onToggleShuffle}
 96 |           title={isShuffled ? "Aleatório: ativado" : "Aleatório: desativado"}
 97 |         >
 98 |           🔀 {isShuffled ? "ON" : "OFF"}
 99 |         </button>
100 |         <button className="ctrl-btn" onClick={onPrev} title="Anterior">
101 |           ⏮
102 |         </button>
103 |         <button
104 |           className="ctrl-btn play-btn"
105 |           onClick={isPlaying ? onPause : onPlay}
106 |           title={isPlaying ? "Pausar" : "Tocar"}
107 |         >
108 |           {isPlaying ? "⏸" : "▶"}
109 |         </button>
110 |         <button className="ctrl-btn" onClick={onNext} title="Próxima">
111 |           ⏭
112 |         </button>
113 |         {onToggleCompact && (
114 |           <button
115 |             className="compact-toggle-btn"
116 |             onClick={onToggleCompact}
117 |             title="Modo compacto"
118 |             aria-label="Modo compacto"
119 |           >
120 |             🔲
121 |           </button>
122 |         )}
123 |       </div>
124 |     </section>
125 |   );
126 | }
